mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("edges=0->1,1->2,2->0,2->3,3->4,4->3","0,1,2;3,4"),
        ("edges=0->1,1->0,1->2","0,1;2"),
        ("edges=0->1,1->2","0;1;2"),
        ("edges=0->1,1->0","0,1"),
        ("edges=0->1,1->2,2->0","0,1,2"),
        ("  \nedges=0->1,1->2,2->0,2->3,3->4,4->3\n  ","0,1,2;3,4"),
        ("\nedges=0->1,1->2,2->0\n","0,1,2")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS strong-components");
}
